import java.io.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.immutable.ImmutableDexFile;import org.jf.dexlib2.writer.pool.DexPool;
public class ScopeNetwork{public static void main(String[]a)throws Exception{var c=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(28));List<ClassDef> all=new ArrayList<>();for(String n:c.getDexEntryNames())for(ClassDef d:c.getEntry(n).getDexFile().getClasses())if(Set.of("Lahtk;","Lahdj;","Lahbw;","Lagyq;","Lrqi;","Lrol;","Lahks;","Lahlv;","Lahmk;","Lahcy;","Lahzz;").contains(d.getType())){all.add(d);System.out.println(n+" "+d.getType());for(Method m:d.getMethods())if(m.getName().equals("a")&&d.getType().equals("Liwy;")&&m.getImplementation()!=null){int line=0;for(var x:m.getImplementation().getDebugItems())if(x instanceof org.jf.dexlib2.iface.debug.LineNumber){var l=(org.jf.dexlib2.iface.debug.LineNumber)x;if(l.getLineNumber()>=480&&l.getLineNumber()<=495)System.out.println("line "+l.getLineNumber()+" address "+l.getCodeAddress());}}}DexPool.writeTo(a[1],new ImmutableDexFile(Opcodes.forApi(28),all));}}
